}
.hero-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 8px; padding: 14px 28px;
  border-radius: var(--radius-sm); font-size: 1rem; font-weight: 600;
  transition: all var(--transition); white-space: nowrap;
}
.btn-primary { background: var(--brand-black); color: var(--brand-lime); }
.btn-primary:hover { background: var(--gray-800); transform: translateY(-2px); box-shadow: var(--shadow-md); }
.btn-secondary { background: var(--white); color: var(--brand-black); border: 2px solid var(--gray-200); }
.btn-secondary:hover { border-color: var(--gray-400); transform: translateY(-2px); }
.btn-lime { background: var(--brand-lime); color: var(--brand-black); }
.btn-lime:hover { filter: brightness(0.95); transform: translateY(-2px); box-shadow: var(--shadow-md); }

/* ===== Hero Tab Switch (Home) ===== */
.hero-tabs { display: inline-flex; background: var(--gray-100); border-radius: 100px; padding: 4px; margin: 0 auto 40px; }
.hero-tab-btn {
  padding: 10px 28px; border-radius: 100px; font-size: 0.938rem;
  font-weight: 600; color: var(--gray-600); transition: all var(--transition);
}
.hero-tab-btn.active { background: var(--white); color: var(--brand-black); box-shadow: var(--shadow-sm); }
.hero-preview { position: relative; max-width: 900px; margin: 0 auto; }
.hero-preview-panel { display: none; }
.hero-preview-panel.active { display: block; animation: fadeInUp 0.4s ease; }
.hero-preview-image {
  background: var(--gray-100); border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200); overflow: hidden; box-shadow: var(--shadow-lg);
  aspect-ratio: 16/9; display: flex; align-items: center; justify-content: center;
}
.hero-preview-image .placeholder {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  color: var(--gray-400);
}
.hero-preview-image .placeholder svg { width: 64px; height: 64px; opacity: 0.4; }
.hero-preview-image .placeholder span { font-size: 0.875rem; font-weight: 500; }

/* ===== Stats Bar ===== */
.stats-bar { padding: 48px 0; background: var(--brand-black); }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; text-align: center; }
.stat-item { padding: 0 16px; }
.stat-value { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.5rem; font-weight: 800; color: var(--brand-lime); }
.stat-label { font-size: 0.938rem; color: rgba(255,255,255,0.7); margin-top: 4px; }

/* ===== Section Common ===== */
.section { padding: 96px 0; }
.section-header { text-align: center; max-width: 700px; margin: 0 auto 60px; }
.section-header h2 { font-size: clamp(2rem, 3.5vw, 2.75rem); margin-bottom: 16px; }
.section-header p { font-size: 1.1rem; color: var(--gray-500); line-height: 1.7; }
.section-label {
  display: inline-block; font-size: 0.813rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--blue); margin-bottom: 12px;
}
.bg-gray { background: var(--gray-50); }
.bg-black { background: var(--brand-black); color: var(--white); }
.bg-black .section-header p { color: rgba(255,255,255,0.65); }
.bg-black .section-label { color: var(--brand-lime); }

/* ===== Product Cards ===== */
.products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.product-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 32px 24px;
  transition: all var(--transition); text-align: left;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--brand-lime); }
.product-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-sm);
