}
.product-card-icon.blue { background: #DBEAFE; color: var(--blue); }
.product-card-icon.lime { background: #F7FEE7; color: #84CC16; }
.product-card-icon.burgundy { background: #FEF2F2; color: var(--brand-burgundy); }
.product-card-icon.purple { background: #F3E8FF; color: #7C3AED; }
.product-card h3 { font-size: 1.2rem; margin-bottom: 8px; }
.product-card p { font-size: 0.938rem; color: var(--gray-500); line-height: 1.6; }
.product-card .card-link {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 16px;
  font-size: 0.875rem; font-weight: 600; color: var(--blue); transition: gap var(--transition);
}
.product-card .card-link:hover { gap: 10px; }

/* ===== Tabbed Feature Section (Why Choose Us) ===== */
.feature-tabs { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; justify-content: center; }
.feature-tab-btn {
  padding: 10px 20px; border-radius: 100px; font-size: 0.875rem;
  font-weight: 600; color: var(--gray-600); background: var(--gray-100);
  transition: all var(--transition); white-space: nowrap;
}
.feature-tab-btn.active { background: var(--brand-black); color: var(--brand-lime); }
.feature-tab-content { display: none; animation: fadeInUp 0.35s ease; }
.feature-tab-content.active { display: block; }
.feature-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.feature-item {
  display: flex; align-items: flex-start; gap: 14px;
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-md); padding: 20px;
  transition: all var(--transition);
}
.feature-item:hover { border-color: var(--brand-lime); box-shadow: var(--shadow-sm); }
.feature-item-icon {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: var(--gray-100); display: flex; align-items: center;
  justify-content: center; flex-shrink: 0;
}
.feature-item-icon svg { width: 18px; height: 18px; }
.feature-item-text h4 { font-size: 0.938rem; margin-bottom: 2px; }
.feature-item-text p { font-size: 0.813rem; color: var(--gray-500); }

/* ===== Testimonials Carousel ===== */
.testimonials-wrapper { position: relative; max-width: 900px; margin: 0 auto; overflow: hidden; }
.testimonials-track { display: flex; transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
.testimonial-card {
  min-width: 100%; padding: 0 8px;
  display: flex; flex-direction: column; align-items: center; text-align: center;
}
.testimonial-quote {
  font-size: 1.2rem; color: var(--gray-700); line-height: 1.7;
  max-width: 700px; margin-bottom: 28px; font-style: italic;
}
.testimonial-author { font-weight: 700; font-size: 1rem; }
.testimonial-role { font-size: 0.875rem; color: var(--gray-500); margin-top: 4px; }
.testimonial-avatar {
  width: 56px; height: 56px; border-radius: 50%; background: var(--gray-200);
  margin-bottom: 12px; display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--gray-400);
}
.carousel-controls { display: flex; align-items: center; justify-content: center; gap: 16px; margin-top: 36px; }
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); color: var(--gray-600);
}
.carousel-btn:hover { border-color: var(--brand-black); color: var(--brand-black); background: var(--gray-50); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; background: var(--gray-300);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--brand-black); width: 28px; border-radius: 5px; }

/* ===== Pricing ===== */
.pricing-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.pricing-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 32px 24px;
  transition: all var(--transition); position: relative;
}
.pricing-card.featured { border-color: var(--brand-black); box-shadow: var(--shadow-lg); }
.pricing-card.featured::before {
  content: 'Most Popular'; position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
